// 在 fontawesome.css / brands.css 里按关键词搜索可用的图标名（临时脚本）
import fs from 'node:fs';

function loadNames(files) {
    const names = new Set();
    for (const f of files) {
        if (!fs.existsSync(f)) continue;
        const css = fs.readFileSync(f, 'utf8');
        for (const rule of css.split('}')) {
            if (!rule.includes('--fa:')) continue;
            for (const m of rule.matchAll(/\.(fa-[a-z0-9-]+)/g)) names.add(m[1]);
        }
    }
    return names;
}

const names = loadNames(['_fa_probe/fontawesome.css', '_fa_probe/brands.css']);
console.log('可用图标名总数:', names.size);

const KEYWORDS = process.argv.slice(2);
for (const kw of KEYWORDS) {
    const hits = [...names].filter(n => n.includes(kw)).sort();
    console.log(`\n--- "${kw}" (${hits.length}) ---`);
    console.log(hits.slice(0, 40).join('  '));
}

