// 收尾校验：范围文件里生成的每个 fa-* 图标是否真实存在、字形是否在 regular 字重里
import fs from 'node:fs';

const SCOPE = [
    'sidepanel.html', 'css/sidepanel.css', 'js/cdn-styles.js',
    'js/modules/sp-core.js', 'js/modules/sp-prompts.js', 'js/modules/sp-scratchpad.js',
    'js/modules/sp-readlater.js', 'js/modules/sp-gallery.js', 'js/modules/sp-tools.js',
    'js/modules/sp-servers.js', 'js/modules/sp-regcode.js', 'js/modules/sp-2fa.js',
    'js/modules/sp-ai-provider.js', 'js/modules/sp-ai-collection.js', 'js/modules/sp-hot.js',
    'js/modules/sp-editor.js', 'js/modules/sp-clock.js'
];

function parseFa(files) {
    const map = new Map();
    for (const f of files) {
        if (!fs.existsSync(f)) continue;
        for (const rule of fs.readFileSync(f, 'utf8').split('}')) {
            if (!rule.includes('--fa:')) continue;
            const cp = rule.match(/--fa:\s*"\\([^"]*)"/);
            if (!cp) continue;
            const code = /^[0-9a-fA-F]{4,6}$/.test(cp[1]) ? parseInt(cp[1], 16) : cp[1].codePointAt(0);
            for (const m of rule.matchAll(/\.(fa-[a-z0-9-]+)/g)) if (!map.has(m[1])) map.set(m[1], code);
        }
    }
    return map;
}

const icons = parseFa(['_fa_probe/fontawesome.css']);
const brands = parseFa(['_fa_probe/brands.css']);
const regularCps = new Set(JSON.parse(fs.readFileSync('_fa_probe/availability.json', 'utf8')).regular);

const STYLE_TOKENS = new Set(['fa-regular', 'fa-solid', 'fa-brands', 'fa-light', 'fa-thin']);
const used = new Map();     // name -> {count, styles:Set}
let scanned = 0;

for (const rel of SCOPE) {
    if (!fs.existsSync(rel)) continue;
    scanned++;
    const src = fs.readFileSync(rel, 'utf8');
    // 属性里的 class="..."（含 JS 模板字符串里的 class="..."）
    for (const m of src.matchAll(/class="([^"]*)"/g)) {
        const toks = m[1].split(/\s+/).filter(Boolean);
        const styles = toks.filter(t => STYLE_TOKENS.has(t));
        for (const t of toks) {
            if (!t.startsWith('fa-') || STYLE_TOKENS.has(t)) continue;
            if (!used.has(t)) used.set(t, { count: 0, styles: new Set() });
            const e = used.get(t);
            e.count++;
            for (const s of styles) e.styles.add(s);
        }
    }
    // JS 里以字符串形式出现的 'fa-xxx'（动态拼接场景）
    for (const m of src.matchAll(/(?:className\s*=\s*|icon:\s*)'([^']*fa-[a-z0-9-]+[^']*)'/g)) {
        const toks = m[1].split(/\s+/).filter(Boolean);
        for (const t of toks) {
            if (!t.startsWith('fa-') || STYLE_TOKENS.has(t)) continue;
            if (!used.has(t)) used.set(t, { count: 0, styles: new Set() });
            used.get(t).count++;
            if (toks.includes('fa-brands')) used.get(t).styles.add('fa-brands');
            else if (toks.includes('fa-solid')) used.get(t).styles.add('fa-solid');
            else used.get(t).styles.add('fa-regular');
        }
    }
}

console.log(`扫描 ${scanned} 个范围文件，用到 ${used.size} 个不同图标名\n`);

const bad = [];
for (const [name, e] of [...used].sort()) {
    const isBrand = e.styles.has('fa-brands');
    const table = isBrand ? brands : icons;
    if (!table.has(name)) { bad.push(`${name}  x${e.count}  -> FA 里不存在这个图标名`); continue; }
    if (!isBrand && e.styles.has('fa-regular') && !regularCps.has(table.get(name))) {
        bad.push(`${name}  x${e.count}  -> regular 字重无字形`);
    }
    if (!isBrand && e.styles.size === 0) {
        bad.push(`${name}  x${e.count}  -> 缺少 fa-regular 风格类（不会显示）`);
    }
}

if (bad.length) {
    console.log('!!! 问题图标 !!!');
    for (const b of bad) console.log('  ' + b);
} else {
    console.log('全部图标名与字形校验通过 ✓');
}

// 抽掉残留的 ligature 文本（.mi 元素里不应该再有文字）
console.log('\n=== .mi 元素里是否还残留文字 ===');
let textLeft = 0;
for (const rel of SCOPE) {
    if (!fs.existsSync(rel)) continue;
    const src = fs.readFileSync(rel, 'utf8');
    for (const m of src.matchAll(/class="[^"]*\bmi\b[^"]*"[^>]*>\s*([^<\s][^<]*?)</g)) {
        console.log(`  ${rel}: ${JSON.stringify(m[1].trim().slice(0, 60))}`);
        textLeft++;
    }
}
if (!textLeft) console.log('  （无残留）');

console.log('\n=== 使用到的图标清单 ===');
