// 用法: node _fa_probe/rewrite.mjs          # 干跑，只报告
//       node _fa_probe/rewrite.mjs --apply  # 真正写入
import fs from 'node:fs';
import { ICON } from './icon-map.mjs';

const APPLY = process.argv.includes('--apply');

const SCOPE = [
    'sidepanel.html',
    'css/sidepanel.css',
    'js/cdn-styles.js',
    'js/modules/sp-core.js',
    'js/modules/sp-prompts.js',
