    'js/modules/sp-ai-collection.js',
    'js/modules/sp-hot.js',
    'js/modules/sp-editor.js',
    'js/modules/sp-clock.js'
];

// ---------- 1. 建立 FA 名字/码点索引，并校验映射表 ----------
function parseFaNames(files) {
    const map = new Map();
    for (const f of files) {
        if (!fs.existsSync(f)) continue;
        for (const rule of fs.readFileSync(f, 'utf8').split('}')) {
            if (!rule.includes('--fa:')) continue;
            const cp = rule.match(/--fa:\s*"\\([0-9a-fA-F]+)"/);
            if (!cp) continue;
            const code = parseInt(cp[1], 16);
            for (const m of rule.matchAll(/\.(fa-[a-z0-9-]+)/g)) if (!map.has(m[1])) map.set(m[1], code);
        }
    }
    return map;
}

const faNames = parseFaNames(['_fa_probe/fontawesome.css', '_fa_probe/brands.css']);
const regularCps = new Set(JSON.parse(fs.readFileSync('_fa_probe/availability.json', 'utf8')).regular);

const resolved = new Map();
const problems = [];
for (const [lig, spec] of Object.entries(ICON)) {
    const cands = Array.isArray(spec) ? spec : [spec];
    let picked = null;
    for (const c of cands) {
        const tokens = c.split(/\s+/);
        const nameTok = tokens.find(t => t.startsWith('fa-') && t !== 'fa-brands' && t !== 'fa-regular' && t !== 'fa-solid');
        if (!nameTok) { problems.push(`${lig}: 缺少图标名 in "${c}"`); continue; }
        if (!faNames.has(nameTok)) { problems.push(`${lig}: FA 里不存在 "${nameTok}"`); continue; }
        const isBrand = tokens.includes('fa-brands');
        if (!isBrand && !regularCps.has(faNames.get(nameTok))) { problems.push(`${lig}: "${nameTok}" 在 regular 字重里没有字形`); continue; }
        picked = c;
        break;
    }
    if (picked) resolved.set(lig, picked);
}

console.log(`映射表共 ${Object.keys(ICON).length} 项，成功解析 ${resolved.size} 项`);
if (problems.length) {
    console.log('\n!!! 映射问题 !!!');
    for (const p of problems) console.log('  ' + p);
}

// ---------- 2. 校验：范围内用到的 ligature 是否都在表里 ----------
const used = new Map();
for (const rel of SCOPE) {
    if (!fs.existsSync(rel)) continue;
    const src = fs.readFileSync(rel, 'utf8');
    for (const m of src.matchAll(/class="[^"]*\bmaterial-icons\b[^"]*"[^>]*>\s*([A-Za-z0-9_]+)\s*</g)) {
        used.set(m[1], (used.get(m[1]) || 0) + 1);
    }
}
const missing = [...used.keys()].filter(n => !resolved.has(n));
console.log(`\n范围内静态 ligature 名称 ${used.size} 个`);
if (missing.length) console.log('!!! 未映射: ' + missing.join(', '));

// ---------- 3. 执行替换 ----------
function rebuildClass(cls, fa) {
    const toks = cls.split(/\s+/).filter(Boolean).map(t => (t === 'material-icons' ? 'mi' : t));
    for (const t of fa.split(/\s+/)) if (!toks.includes(t)) toks.push(t);
    return toks.join(' ');
}

const stats = {};
const leftovers = [];

function transform(rel, src) {
    let n = 0;
    // 3a. 静态：<span ... class="...material-icons..." ...>ligature</span>
    src = src.replace(
        /(<span\b[^>]*?)class="([^"]*\bmaterial-icons\b[^"]*)"([^>]*>)([A-Za-z0-9_]+)(<\/span>)/g,
        (m, pre, cls, post, name, end) => {
            const fa = resolved.get(name);
            if (!fa) return m;
            n++;
            return `${pre}class="${rebuildClass(cls, fa)}"${post}${end}`;
        }
    );
    stats[rel] = n;
    return src;
}

const edits = new Map();
for (const rel of SCOPE) {
    if (!fs.existsSync(rel)) continue;
    edits.set(rel, transform(rel, fs.readFileSync(rel, 'utf8')));
}

// ---------- 4. 定点处理动态用法 ----------
function patch(rel, from, to, label) {
    const src = edits.get(rel);
    if (src === undefined) { leftovers.push(`${rel}: 文件不存在（${label}）`); return; }
    if (!src.includes(from)) { leftovers.push(`${rel}: 未找到待替换片段（${label}）`); return; }
    edits.set(rel, src.replace(from, to));
}

