console.log('\n=== 每个文件的静态替换数 ===');
for (const [rel, n] of Object.entries(stats)) if (n) console.log(String(n).padStart(4), rel);

console.log('\n=== 残留 / 需人工确认 ===');
if (!leftovers.length) console.log('  （无）');
for (const l of leftovers) console.log('  ' + l);

console.log('\n=== 最终写入范围 ===');
console.log(SCOPE.join('\n'));

if (APPLY) {
    for (const [rel, src] of edits) fs.writeFileSync(rel, src);
