// 把侧边栏范围内的 Google Material Icons 全部替换为 Font Awesome Pro 线框图标
// 用法: node _fa_probe/rewrite.mjs          # 干跑，只报告
//       node _fa_probe/rewrite.mjs --apply  # 真正写入
import fs from 'node:fs';
import { ICON } from './icon-map.mjs';

const APPLY = process.argv.includes('--apply');

const SCOPE = [
    'sidepanel.html',
    'css/sidepanel.css',
    'js/cdn-styles.js',
    'js/modules/sp-core.js',
    'js/modules/sp-prompts.js',
    'js/modules/sp-scratchpad.js',
    'js/modules/sp-readlater.js',
    'js/modules/sp-gallery.js',
    'js/modules/sp-tools.js',
    'js/modules/sp-servers.js',
    'js/modules/sp-regcode.js',
    'js/modules/sp-2fa.js',
    'js/modules/sp-ai-provider.js',
    'js/modules/sp-ai-collection.js',
    'js/modules/sp-hot.js',
    'js/modules/sp-editor.js',
    'js/modules/sp-clock.js'
];

// ---------- 1. 建立 FA 名字/码点索引，并校验映射表 ----------
function parseFaNames(files) {
    const map = new Map();
    for (const f of files) {
        if (!fs.existsSync(f)) continue;
        for (const rule of fs.readFileSync(f, 'utf8').split('}')) {
            if (!rule.includes('--fa:')) continue;
            // FA 里 --fa 有两种写法："\f002"（十六进制码点）和 "\+"（转义的字面字符，如 + 、 * 、 - ）
            const cp = rule.match(/--fa:\s*"\\([^"]*)"/);
            if (!cp) continue;
            const body = cp[1];
            const code = /^[0-9a-fA-F]{4,6}$/.test(body) ? parseInt(body, 16) : body.codePointAt(0);
            for (const m of rule.matchAll(/\.(fa-[a-z0-9-]+)/g)) if (!map.has(m[1])) map.set(m[1], code);
        }
    }
    return map;
}

const faNames = parseFaNames(['_fa_probe/fontawesome.css', '_fa_probe/brands.css']);
const regularCps = new Set(JSON.parse(fs.readFileSync('_fa_probe/availability.json', 'utf8')).regular);

const resolved = new Map();
const problems = [];
for (const [lig, spec] of Object.entries(ICON)) {
    const cands = Array.isArray(spec) ? spec : [spec];
    let picked = null;
    for (const c of cands) {
        const tokens = c.split(/\s+/);
        const nameTok = tokens.find(t => t.startsWith('fa-') && t !== 'fa-brands' && t !== 'fa-regular' && t !== 'fa-solid');
        if (!nameTok) { problems.push(`${lig}: 缺少图标名 in "${c}"`); continue; }
        if (!faNames.has(nameTok)) { problems.push(`${lig}: FA 里不存在 "${nameTok}"`); continue; }
        const isBrand = tokens.includes('fa-brands');
        if (!isBrand && !regularCps.has(faNames.get(nameTok))) { problems.push(`${lig}: "${nameTok}" 在 regular 字重里没有字形`); continue; }
        picked = c;
        break;
    }
    if (picked) resolved.set(lig, picked);
}

console.log(`映射表共 ${Object.keys(ICON).length} 项，成功解析 ${resolved.size} 项`);
if (problems.length) {
    console.log('\n!!! 映射问题 !!!');
    for (const p of problems) console.log('  ' + p);
}

// ---------- 2. 校验：范围内用到的 ligature 是否都在表里 ----------
const used = new Map();
for (const rel of SCOPE) {
    if (!fs.existsSync(rel)) continue;
    const src = fs.readFileSync(rel, 'utf8');
    for (const m of src.matchAll(/class="[^"]*\bmaterial-icons\b[^"]*"[^>]*>\s*([A-Za-z0-9_]+)\s*</g)) {
        used.set(m[1], (used.get(m[1]) || 0) + 1);
    }
}
const missing = [...used.keys()].filter(n => !resolved.has(n));
console.log(`\n范围内静态 ligature 名称 ${used.size} 个`);
if (missing.length) console.log('!!! 未映射: ' + missing.join(', '));

// ---------- 3. 执行替换 ----------
function rebuildClass(cls, fa) {
    const toks = cls.split(/\s+/).filter(Boolean).map(t => (t === 'material-icons' ? 'mi' : t));
    for (const t of fa.split(/\s+/)) if (!toks.includes(t)) toks.push(t);
    return toks.join(' ');
}

const stats = {};
const leftovers = [];

function transform(rel, src) {
    let n = 0;
    // 3a. 静态：<span ... class="...material-icons..." ...>ligature</span>
    src = src.replace(
        /(<span\b[^>]*?)class="([^"]*\bmaterial-icons\b[^"]*)"([^>]*>)([A-Za-z0-9_]+)(<\/span>)/g,
        (m, pre, cls, post, name, end) => {
            const fa = resolved.get(name);
            if (!fa) return m;
            n++;
            return `${pre}class="${rebuildClass(cls, fa)}"${post}${end}`;
        }
    );
    stats[rel] = n;
    return src;
}

const edits = new Map();
for (const rel of SCOPE) {
    if (!fs.existsSync(rel)) continue;
    edits.set(rel, transform(rel, fs.readFileSync(rel, 'utf8')));
}

// ---------- 4. 定点处理动态用法 ----------
// 注意：仓库里 HTML 是 LF、JS 模块是 CRLF，所以按行拆分后重新拼接，兼容两种换行。
function escapeRe(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

function patch(rel, from, to, label) {
    const src = edits.get(rel);
    if (src === undefined) { leftovers.push(`${rel}: 文件不存在（${label}）`); return; }
    const eol = src.includes('\r\n') ? '\r\n' : '\n';
    const re = new RegExp(from.split('\n').map(escapeRe).join('\\r?\\n'));
    if (!re.test(src)) { leftovers.push(`${rel}: 未找到待替换片段（${label}）`); return; }
    edits.set(rel, src.replace(re, () => to.replace(/\n/g, eol)));
}

// sp-ai-collection.js：JS 直接拼 className / textContent
patch('js/modules/sp-ai-collection.js',
    "            newtabIcon.className = 'material-icons';\n            newtabIcon.textContent = 'open_in_new';",
    "            newtabIcon.className = 'mi fa-regular fa-arrow-up-right-from-square';",
    'ai-tag newtab');
patch('js/modules/sp-ai-collection.js',
    "        dragHandle.className = 'material-icons ai-drag-handle';\n        dragHandle.textContent = 'drag_indicator';",
    "        dragHandle.className = 'mi fa-regular fa-grip-dots-vertical ai-drag-handle';",
    'ai-all drag handle');
patch('js/modules/sp-ai-collection.js',
    "            checkIcon.className = 'material-icons';\n            checkIcon.textContent = 'check_circle';",
    "            checkIcon.className = 'mi fa-regular fa-circle-check';",
    'ai-all check');
patch('js/modules/sp-ai-collection.js',
    "            ntIcon.className = 'material-icons';\n            ntIcon.textContent = 'open_in_new';",
    "            ntIcon.className = 'mi fa-regular fa-arrow-up-right-from-square';",
    'ai-all newtab');
patch('js/modules/sp-ai-collection.js',
    "        editBtn.className = 'material-icons';\n        editBtn.textContent = 'edit';",
    "        editBtn.className = 'mi fa-regular fa-pen-to-square';",
    'ai-all edit');

// sp-tools.js 拖动把手
patch('js/modules/sp-tools.js',
    "        handle.className = 'material-icons tool-drag-handle';\n        handle.textContent = 'drag_indicator';",
    "        handle.className = 'mi fa-regular fa-grip-dots-vertical tool-drag-handle';",
    'tool drag handle');

// sp-servers.js 操作系统图标（三元表达式里的名字）
patch('js/modules/sp-servers.js',
    "const osIcon = srv.os === 'Windows' ? 'window' : (srv.os === 'Other' ? 'help_outline' : 'terminal');",
    "const osIcon = srv.os === 'Windows' ? 'fa-window-maximize' : (srv.os === 'Other' ? 'fa-circle-question' : 'fa-terminal');",
    'osIcon 取值');
patch('js/modules/sp-servers.js',
    'class="material-icons" style="font-size:16px;color:#6366f1;">${osIcon}</span>',
    'class="mi fa-regular ${osIcon}" style="font-size:16px;color:#6366f1;"></span>',
    'osIcon class');

// sp-editor.js 右键菜单图标名
patch('js/modules/sp-editor.js',
    `'<span class="material-icons">' + esc(it.icon || 'chevron_right') + '</span>'`,
    `'<span class="mi fa-regular ' + esc(it.icon || 'fa-chevron-right') + '"></span>'`,
    'editor ctx icon');

// sp-editor.js 里 icon: 'ligature' 数据
{
    const rel = 'js/modules/sp-editor.js';
    let src = edits.get(rel);
    let n = 0;
    src = src.replace(/icon:\s*'([a-z_0-9]+)'/g, (m, name) => {
        const fa = resolved.get(name);
        if (!fa) { leftovers.push(`${rel}: icon: '${name}' 未映射`); return m; }
        const nameTok = fa.split(/\s+/).find(t => t.startsWith('fa-') && !['fa-brands', 'fa-regular', 'fa-solid'].includes(t));
        n++;
        return `icon: '${nameTok}'`;
    });
    stats[rel] = (stats[rel] || 0) + n;
    edits.set(rel, src);
}

// ---------- 5. CSS / 残留 material-icons 统一改名 ----------
for (const [rel, src] of edits) {
    let out = src;
    if (rel === 'css/sidepanel.css') {
        out = out.replace(/\bmaterial-icons\b/g, 'mi');
    }
    const left = [...out.matchAll(/material-icons/g)];
    if (left.length) leftovers.push(`${rel}: 残留 material-icons x${left.length}`);
    edits.set(rel, out);
}

// ---------- 6. 移除 Google Material Icons 依赖 ----------
// cdn-styles.js：删掉 Material Icons 条目 + ligature 防闪逻辑
{
    const rel = 'js/cdn-styles.js';
    let src = edits.get(rel);
    const before = src;
    src = src.replace(/\n\s*\/\/ Material Icons\n\s*'https:\/\/fonts\.googleapis\.com\/icon\?family=Material\+Icons',/, '');
    if (src === before) leftovers.push(`${rel}: 未删除 Material Icons 样式条目`);
    edits.set(rel, src);
}

// ---------- 7. 报告 ----------
console.log('\n=== 每个文件的静态替换数 ===');
for (const [rel, n] of Object.entries(stats)) if (n) console.log(String(n).padStart(4), rel);

console.log('\n=== 残留 / 需人工确认 ===');
if (!leftovers.length) console.log('  （无）');
for (const l of leftovers) console.log('  ' + l);

console.log('\n=== 最终写入范围 ===');
console.log(SCOPE.join('\n'));

if (APPLY) {
    for (const [rel, src] of edits) fs.writeFileSync(rel, src);
    console.log('\n已写入。');
} else {
    console.log('\n（干跑，未写入。加 --apply 生效）');
}
